// Determine which reminders are due, using safe Africa/Cairo string comparison.
// reminder_time / follow_up_time / snooze_until are stored as 'YYYY-MM-DD HH:mm:ss'
// which sorts correctly as plain strings, avoiding runtime-timezone Date bugs.

const cairoNowStr = $now.setZone('Africa/Cairo').toFormat('yyyy-MM-dd HH:mm:ss');

const results = [];

for (const item of items) {
  const reminder = item.json;

  // =========================
  // INITIAL REMINDER
  // =========================
  if (
    reminder.status === 'pending' &&
    !reminder.sent_at &&
    reminder.reminder_time &&
    reminder.reminder_time <= cairoNowStr
  ) {
    results.push({ json: { ...reminder, action: 'send_reminder' } });
    continue;
  }

  // =========================
  // FOLLOW-UP
  // =========================
  if (
    reminder.status === 'sent' &&
    reminder.follow_up_time &&
    reminder.follow_up_sent !== 'true' &&
    reminder.follow_up_sent !== true &&
    reminder.follow_up_time <= cairoNowStr
  ) {
    results.push({ json: { ...reminder, action: 'send_follow_up' } });
    continue;
  }

  // =========================
  // SNOOZE
  // =========================
  if (
    reminder.status === 'snoozed' &&
    reminder.snooze_until &&
    reminder.snooze_until <= cairoNowStr
  ) {
    results.push({ json: { ...reminder, action: 'send_snoozed_reminder' } });
  }
}

return results;
